"""Generated by /sdlc-studio test-automation (brownfield validation subset).

Pure-logic tests for the Python STT workers' helper functions (TS0002 / US0009).

These import the real worker modules from
`crates/contextcall-core/src/transcription/`. The workers import heavy ML
dependencies at module top (numpy, faster_whisper, torch, transformers), so each
test group is guarded with ``pytest.importorskip`` — in a basic CI environment
without those deps the group SKIPS cleanly rather than erroring. Install the
worker venvs (see ContextCall STT setup) to run them locally.

Covered: worker device normalization, model cache-key format, and the gated-repo
error normalization. The JSON transcribe round-trip, model loading, and
diarization require the full ML stack + audio and are intentionally not unit
tested here (they belong to integration runs against installed venvs).
"""

import importlib.util
import sys
from pathlib import Path

import pytest

WORKER_DIR = (
    Path(__file__).resolve().parents[3]
    / "crates"
    / "contextcall-core"
    / "src"
    / "transcription"
)


def _load_worker(module_name: str):
    """Import a worker module by file path (its dir is not a package)."""
    path = WORKER_DIR / f"{module_name}.py"
    spec = importlib.util.spec_from_file_location(module_name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    return module


# ---------------------------------------------------------------------------
# faster-whisper worker (TS0002 / US0009)
# ---------------------------------------------------------------------------

class TestFasterWhisperWorker:
    """TS0002: faster-whisper worker helpers."""

    @pytest.fixture(scope="class")
    def worker(self):
        pytest.importorskip("numpy")
        pytest.importorskip("faster_whisper")
        return _load_worker("faster_whisper_worker")

    def test_tc125_normalize_device_auto_to_cpu(self, worker):
        """TC125 (US0009 AC6): 'auto' resolves to 'cpu'."""
        assert worker.normalize_device("auto") == "cpu"
        assert worker.normalize_device("") == "cpu"
        assert worker.normalize_device("AUTO") == "cpu"

    def test_tc125_normalize_device_passthrough(self, worker):
        """TC125: explicit devices are lowercased and passed through."""
        assert worker.normalize_device("CUDA") == "cuda"
        assert worker.normalize_device("cpu") == "cpu"

    def test_tc121_model_key_format(self, worker):
        """TC121 (US0009 AC2): cache key is 'model::device::compute_type'."""
        assert (
            worker.model_key("medium", "cpu", "int8") == "medium::cpu::int8"
        )


