class TestCohereTranscribeWorker:
    """TS0002: Cohere Transcribe worker helpers."""

    @pytest.fixture(scope="class")
    def worker(self):
        pytest.importorskip("torch")
        pytest.importorskip("transformers")
        pytest.importorskip("numpy")
        return _load_worker("cohere_transcribe_worker")

    def test_tc125_normalize_device_cpu(self, worker):
        """TC125 (US0009 AC6): 'cpu' → ('cpu', float32)."""
        import torch

        device, dtype = worker.normalize_device("cpu")
        assert device == "cpu"
        assert dtype == torch.float32

    def test_tc125_cuda_without_device_raises(self, worker):
        """TC125: requesting cuda with no CUDA device raises the exact error."""
        import torch

        if torch.cuda.is_available():
            pytest.skip("CUDA available — negative path not exercised")
        with pytest.raises(RuntimeError) as exc:
            worker.normalize_device("cuda")
        assert "CUDA was requested for Cohere Transcribe" in str(exc.value)

    def test_tc124_gated_repo_error_normalized(self, worker):
        """TC124 (US0009 AC5): gated-repo errors map to the user-facing message."""
        msg = worker.normalize_model_load_error(
            Exception("Cannot access gated repo for url ..."),
            "CohereLabs/cohere-transcribe-03-2026",
        )
        assert "does not have access to the gated model" in msg
        assert "huggingface.co/CohereLabs/cohere-transcribe-03-2026" in msg

    def test_tc124_non_gated_error_passthrough(self, worker):
        """TC124: unrelated errors are returned unchanged."""
        msg = worker.normalize_model_load_error(
            Exception("disk full"), "some/model"
        )
        assert msg == "disk full"
